const CharacterProgressBar = ({
  currentLength,
  recommendedMin,
  recommendedMax,
  label = 'Chars',
  showTextLabel = true,
}: {
  currentLength: number;
  recommendedMin: number;
  recommendedMax: number;
  label?: string;
  showTextLabel?: boolean;
}) => {
  const percentage = Math.min(100, Math.round((currentLength / recommendedMax) * 100));

  let colorClass = 'bg-[#E59500]';
  let badgeClass = 'bg-amber-500/20 text-amber-400 border border-amber-500/30';
  let statusText = 'Short';

  if (currentLength === 0) {
    colorClass = 'bg-rose-500';
    badgeClass = 'bg-rose-500/20 text-rose-400 border border-rose-500/30';
    statusText = 'Missing';
  } else if (currentLength < recommendedMin) {
    colorClass = 'bg-amber-500';
    badgeClass = 'bg-amber-500/20 text-amber-400 border border-amber-500/30';
    statusText = 'Under Min';
  } else if (currentLength >= recommendedMin && currentLength <= recommendedMax) {
    colorClass = 'bg-emerald-500';
    badgeClass = 'bg-emerald-500/20 text-emerald-400 border border-emerald-500/30';
    statusText = 'Optimal Length';
  } else {
    colorClass = 'bg-rose-500';
    badgeClass = 'bg-rose-500/20 text-rose-400 border border-rose-500/30';
    statusText = 'Exceeds Recommended Max';
  }

  return (
    <div className="space-y-1.5 mt-1">
      {showTextLabel && (
        <div className="flex justify-between items-center text-[10px] font-mono">
          <span className={`px-2 py-0.5 rounded text-[9px] font-bold uppercase ${badgeClass}`}>
            {statusText}
          </span>
          <span className="text-[#A69D92] font-semibold">
            {currentLength} / {recommendedMax} {label}
          </span>
        </div>
      )}
      <div className="w-full bg-[#15120E] h-2 rounded-full overflow-hidden border border-[#2C2419]">
        <div
          className={`h-full transition-all duration-300 ${colorClass}`}
          style={{ width: `${percentage}%` }}
        />
      </div>
    </div>
  );
};

const GoogleSearchPreview = ({
  url,
  title,
  description,
  keywords,
  initialViewMode = 'desktop',
}: {
  url: string;
  title: string;
  description: string;
  keywords?: string;
  initialViewMode?: 'desktop' | 'mobile';
}) => {
  const [viewMode, setViewMode] = useState<'desktop' | 'mobile'>(initialViewMode);

  const displayTitle = title.trim() || 'Untitled Page - Search Title';
  const displayDesc = description.trim() || 'No meta description provided. Search engines will extract a snippet automatically from page body text.';
  const displayUrl = url.startsWith('http') ? url : `https://rizwansaddique.site${url.startsWith('/') ? '' : '/'}${url}`;

  const formattedUrlBreadcrumb = displayUrl
    .replace('https://', '')
    .split('/')
    .filter(Boolean)
    .join(' › ');

  const titleLen = title.trim().length;
  const descLen = description.trim().length;

  const isTitleIdeal = titleLen >= 40 && titleLen <= 60;
  const isTitleOver = titleLen > 60;

  const isDescIdeal = descLen >= 110 && descLen <= 160;
  const isDescOver = descLen > 160;

  return (
    <div className="bg-[#15120E] border border-[#2C2419] rounded-2xl p-4 sm:p-5 space-y-4 shadow-xl">
      <div className="flex items-center justify-between border-b border-[#2C2419]/60 pb-3">
        <div className="flex items-center gap-2">
          <Search className="w-4 h-4 text-[#E59500]" />
          <h5 className="text-xs font-bold font-mono text-[#F9F7F2] uppercase tracking-wider">
            Google Search Engine Result Preview
          </h5>
        </div>
        <div className="flex items-center gap-1 bg-[#231F17] border border-[#2C2419] p-0.5 rounded-lg">
          <button
            type="button"
            onClick={() => setViewMode('desktop')}
            className={`px-2.5 py-1 text-[10px] font-mono font-bold rounded-md transition-all cursor-pointer ${viewMode === 'desktop'
              ? 'bg-[#E59500] text-[#15120E]'
              : 'text-[#A69D92] hover:text-white'
              }`}
          >
            Desktop
          </button>
          <button
            type="button"
            onClick={() => setViewMode('mobile')}
            className={`px-2.5 py-1 text-[10px] font-mono font-bold rounded-md transition-all cursor-pointer ${viewMode === 'mobile'
              ? 'bg-[#E59500] text-[#15120E]'
              : 'text-[#A69D92] hover:text-white'
              }`}
          >
            Mobile
          </button>
        </div>
      </div>

      {/* Google Search Snippet Card */}
      <div
        className={`bg-[#18191a] border border-[#303134] p-4 rounded-xl space-y-1.5 font-sans transition-all ${viewMode === 'mobile' ? 'max-w-sm mx-auto shadow-2xl border-amber-500/30' : 'w-full'
          }`}
      >
        {/* Favicon & Breadcrumb */}
        <div className="flex items-center gap-2 text-[12px] text-[#bdc1c6] truncate">
          <div className="w-5 h-5 rounded-full bg-[#303134] flex items-center justify-center shrink-0 border border-white/10 text-[9px] font-bold text-[#E59500]">
            RS
          </div>
          <div className="truncate flex items-center gap-1">
            <span className="font-medium text-[#e8eaed]">rizwansaddique.site</span>
            <span className="text-[#9aa0a6] font-mono text-[11px] truncate">
              › {formattedUrlBreadcrumb.replace('rizwansaddique.site', '').replace(/^ › /, '') || 'home'}
            </span>
          </div>
        </div>

        {/* Title Link */}
        <div className="text-[18px] sm:text-[20px] font-normal leading-snug text-[#8ab4f8] hover:underline cursor-pointer tracking-normal line-clamp-1">
          {displayTitle}
        </div>

        {/* Snippet Body */}
        <div className="text-[13px] text-[#bdc1c6] leading-relaxed line-clamp-2">
          {displayDesc}
        </div>
      </div>

      {/* Real-time Metric Gauges & Visual Progress Bars */}
      <div className="grid grid-cols-1 sm:grid-cols-2 gap-3 pt-1">
        <div className="bg-[#231F17]/60 border border-[#2C2419] p-3 rounded-xl space-y-2">
          <div className="flex items-center justify-between">
            <div>
              <div className="text-[10px] font-mono text-[#6B6053] uppercase font-bold">Meta Title Tag</div>
              <div className="text-xs font-bold text-[#F9F7F2] font-mono mt-0.5">
                {titleLen} / 60 Chars
              </div>
            </div>
            <span
              className={`px-2 py-0.5 rounded text-[9px] font-mono font-bold uppercase ${isTitleOver
                ? 'bg-rose-500/20 text-rose-400 border border-rose-500/30'
                : isTitleIdeal
                  ? 'bg-emerald-500/20 text-emerald-400 border border-emerald-500/30'
                  : titleLen === 0
                    ? 'bg-rose-500/20 text-rose-400 border border-rose-500/30'
                    : 'bg-amber-500/20 text-amber-400 border border-amber-500/30'
                }`}
            >
              {isTitleOver ? 'Truncated' : isTitleIdeal ? 'Optimal' : titleLen === 0 ? 'Missing' : 'Short'}
            </span>
          </div>
          <CharacterProgressBar currentLength={titleLen} recommendedMin={40} recommendedMax={60} showTextLabel={false} />
        </div>

        <div className="bg-[#231F17]/60 border border-[#2C2419] p-3 rounded-xl space-y-2">
          <div className="flex items-center justify-between">
            <div>
              <div className="text-[10px] font-mono text-[#6B6053] uppercase font-bold">Meta Description</div>
              <div className="text-xs font-bold text-[#F9F7F2] font-mono mt-0.5">
                {descLen} / 160 Chars
              </div>
            </div>
            <span
              className={`px-2 py-0.5 rounded text-[9px] font-mono font-bold uppercase ${isDescOver
                ? 'bg-rose-500/20 text-rose-400 border border-rose-500/30'
                : isDescIdeal
                  ? 'bg-emerald-500/20 text-emerald-400 border border-emerald-500/30'
                  : descLen === 0
                    ? 'bg-rose-500/20 text-rose-400 border border-rose-500/30'
                    : 'bg-amber-500/20 text-amber-400 border border-amber-500/30'
                }`}
            >
              {isDescOver ? 'Truncated' : isDescIdeal ? 'Optimal' : descLen === 0 ? 'Missing' : 'Short'}
            </span>
          </div>
          <CharacterProgressBar currentLength={descLen} recommendedMin={110} recommendedMax={160} showTextLabel={false} />
        </div>
      </div>

      {keywords && keywords.trim().length > 0 && (
        <div className="pt-2 border-t border-[#2C2419]/50 flex flex-wrap items-center gap-1.5">
          <span className="text-[10px] font-mono text-[#6B6053] uppercase mr-1">Target Keywords:</span>
          {keywords.split(',').map((kw, kIdx) => (
            <span key={kIdx} className="text-[10px] font-mono bg-[#231F17] text-[#A69D92] px-2 py-0.5 rounded-md border border-[#2C2419]">
              {kw.trim()}
            </span>
          ))}
        </div>
      )}
    </div>
  );
};

