function ToolIcon({ item, className = "w-5 h-5" }: { item: ToolStackItem; className?: string }) {
  if (item.logoUrl) {
    return (
      <img loading="lazy"
        src={item.logoUrl}
        alt={item.name}
        className={`${className} object-contain rounded-md`}
        referrerPolicy="no-referrer"
      />
    );
  }

  const nameLower = (item.name || '').toLowerCase();
  const iconKey = (item.iconName || '').toLowerCase();

  // Official Brand Vector SVGs for pixel-perfect presentation
  if (iconKey === 'googleads' || nameLower.includes('google ads')) {
    return (
      <svg className={className} viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
        <path d="M4.7 15.6L1.8 10.6C1.2 9.5 1.6 8.1 2.7 7.5L8.7 4C9.8 3.4 11.2 3.8 11.8 4.9L14.7 9.9C15.3 11 14.9 12.4 13.8 13L7.8 16.5C6.7 17.1 5.3 16.7 4.7 15.6Z" fill="#F4B400" />
        <path d="M19.3 8.4L13.3 18.8C12.7 19.9 11.3 20.3 10.2 19.7L7.3 18.1L16.3 2.5C17.4 1.9 18.8 2.3 19.4 3.4L20.8 5.8C21.4 6.9 20.4 7.8 19.3 8.4Z" fill="#4285F4" />
        <circle cx="5" cy="18" r="3" fill="#34A853" />
      </svg>
    );
  }

  if (iconKey === 'meta' || nameLower.includes('meta')) {
    return (
      <svg className={className} viewBox="0 0 24 24" fill="none">
        <path d="M16.7 5C14.8 5 13.2 6.1 12 7.7 10.8 6.1 9.2 5 7.3 5 4.1 5 1.5 7.7 1.5 11c0 3.7 3.2 7 7.3 7 2.2 0 4.1-1.1 5.2-2.7 1.1 1.6 3 2.7 5.2 2.7 4.1 0 7.3-3.3 7.3-7 0-3.3-2.6-6-6.8-6zm-9.4 11c-2.7 0-4.8-2.2-4.8-5s2.1-5 4.8-5c1.7 0 3.2 1 4.1 2.5-1 1.7-2.3 4.6-4.1 7.5zm9.4 0c-1.8-2.9-3.1-5.8-4.1-7.5.9-1.5 2.4-2.5 4.1-2.5 2.7 0 4.8 2.2 4.8 5s-2.1 5-4.8 5z" fill="#0668E1" />
      </svg>
    );
  }

  if (iconKey === 'shopify' || nameLower.includes('shopify')) {
    return (
      <svg className={className} viewBox="0 0 24 24" fill="none">
        <path d="M18.8 6.5s-1-.3-1.4.1c-.4.4-.8 1.5-.9 2.1 0 0-.7-.3-1.6-.2-1.4.2-2.7 1.5-3.2 2.7-.4-1.2-1.3-2.4-2.6-2.6-.9-.1-1.7.2-1.7.2s-.3-1-.8-1.5C6.1 6.8 5.2 7 5.2 7L3 17.5 16 21l5-12.7-2.2-1.8z" fill="#95BF47" />
        <path d="M15.5 8.7s-1-.3-1.4.1c-.4.4-.8 1.5-.9 2.1L18.8 6.5s-1-.3-1.4.1c-.4.4-.8 1.5-.9 2.1z" fill="#5E8E3E" />
        <path d="M12.5 11.5l1.5 6.5-4-1-2.5-5.5s1.2-.5 2.5-.2c1.3.3 2.5.2 2.5.2z" fill="#FFFFFF" opacity="0.9" />
      </svg>
    );
  }

  if (iconKey === 'website' || nameLower.includes('website') || nameLower.includes('web dev')) {
    return (
      <svg className={className} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
        <rect x="2" y="3" width="20" height="14" rx="2" ry="2" fill="#1C1712" stroke="#61DAFB" />
        <line x1="8" y1="21" x2="16" y2="21" stroke="#61DAFB" />
        <line x1="12" y1="17" x2="12" y2="21" stroke="#61DAFB" />
        <polyline points="7 9 5 11 7 13" stroke="#61DAFB" />
        <polyline points="17 9 19 11 17 13" stroke="#61DAFB" />
        <line x1="13" y1="8" x2="11" y2="14" stroke="#61DAFB" />
      </svg>
    );
  }

  if (iconKey === 'mobileapp' || nameLower.includes('mobile app') || nameLower.includes('app dev')) {
    return (
      <svg className={className} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
        <rect x="5" y="2" width="14" height="20" rx="3" fill="#1C1712" stroke="#02569B" />
        <path d="M12 18h.01" stroke="#02569B" strokeWidth="3" />
        <path d="M9 7h6" stroke="#02569B" />
        <path d="M9 10h4" stroke="#02569B" />
        <circle cx="12" cy="13.5" r="1.5" fill="#02569B" />
      </svg>
    );
  }

  if (iconKey === 'seo' || nameLower.includes('seo')) {
    return (
      <svg className={className} viewBox="0 0 24 24" fill="none">
        <circle cx="10.5" cy="10.5" r="7.5" stroke="#E59500" strokeWidth="2.5" fill="none" />
        <line x1="16" y1="16" x2="21" y2="21" stroke="#E59500" strokeWidth="3" strokeLinecap="round" />
        <path d="M7 11l2.5 2.5L14 8" stroke="#E59500" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" />
      </svg>
    );
  }

  if (iconKey === 'gtm' || nameLower.includes('tag manager')) {
    return (
      <svg className={className} viewBox="0 0 24 24" fill="none">
        <path d="M12 2L3 7v10l9 5 9-5V7l-9-5z" fill="#24A1DE" opacity="0.2" />
        <path d="M12 2L3 7l9 5 9-5-9-5z" fill="#24A1DE" />
        <path d="M3 7v10l9 5V12L3 7z" fill="#1A80B6" />
        <path d="M21 7v10l-9 5V12l9-5z" fill="#29B6F6" />
      </svg>
    );
  }

  if (iconKey === 'analytics' || nameLower.includes('analytics')) {
    return (
      <svg className={className} viewBox="0 0 24 24" fill="none">
        <rect x="3" y="14" width="4.5" height="7" rx="1.5" fill="#F9AB00" />
        <rect x="9.75" y="8" width="4.5" height="13" rx="1.5" fill="#F9AB00" />
        <rect x="16.5" y="3" width="4.5" height="18" rx="1.5" fill="#E37400" />
        <circle cx="5.25" cy="10" r="2.25" fill="#F9AB00" />
      </svg>
    );
  }

  if (iconKey === 'figma' || nameLower.includes('figma')) {
    return (
      <svg className={className} viewBox="0 0 24 24" fill="none">
        <path d="M8 24c2.2 0 4-1.8 4-4v-4H8c-2.2 0-4 1.8-4 4s1.8 4 4 4z" fill="#0ACF83" />
        <path d="M4 12c0-2.2 1.8-4 4-4h4v8H8c-2.2 0-4-1.8-4-4z" fill="#A259FF" />
        <path d="M4 4c0-2.2 1.8-4 4-4h4v8H8C5.8 8 4 6.2 4 4z" fill="#F24E1E" />
        <path d="M12 0h4c2.2 0 4 1.8 4 4s-1.8 4-4 4h-4V0z" fill="#FF7262" />
        <path d="M20 12c0 2.2-1.8 4-4 4s-4-1.8-4-4 1.8-4 4-4 4 1.8 4 4z" fill="#1ABCFE" />
      </svg>
    );
  }

  if (item.iconName) {
    const IconComponent = (() => {
      switch (item.iconName) {
        case 'Code': return Code;
        case 'Terminal': return Terminal;
        case 'Globe': return Globe;
        case 'Database': return Database;
        case 'Smartphone': return Smartphone;
        case 'Laptop': return Laptop;
        case 'Cpu': return Cpu;
        case 'Palette': return Palette;
        case 'Monitor': return Monitor;
        case 'Wrench': return Wrench;
        case 'Layers': return Layers;
        case 'PenTool': return PenTool;
        case 'Sparkles': return Sparkles;
        case 'Calculator': return Calculator;
        case 'TrendingUp': return TrendingUp;
        case 'Target': return Target;
        case 'Search': return Search;
        case 'Settings': return Settings;
        default: return null;
      }
    })();

    if (IconComponent) {
      return <IconComponent className={className} style={{ color: item.color }} />;
    }
  }

  // Fallback: simple elegant colored indicator circle
  return (
    <span
      className="w-3.5 h-3.5 rounded-full inline-block border border-[#2C2419]"
      style={{ backgroundColor: item.color }}
    />
  );
}

const GSCCarousel = ({ items }: { items: any[] }) => {
  const [currentPage, setCurrentPage] = React.useState(0);
  const itemsPerPage = 5;
  const totalPages = Math.ceil(items.length / itemsPerPage);

  const handleNext = () => {
    setCurrentPage((prev) => (prev + 1) % totalPages);
  };

  const handlePrev = () => {
    setCurrentPage((prev) => (prev - 1 + totalPages) % totalPages);
  };

  const visibleItems = items.slice(currentPage * itemsPerPage, (currentPage + 1) * itemsPerPage);

  return (
    <div className="w-full">
      <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 lg:grid-cols-5 gap-5 pb-4">
        <AnimatePresence mode="popLayout">
          {visibleItems.map((item, idx) => (
            <motion.a
              key={`${item.id || item.domain}-${currentPage}-${idx}`}
              href={item.url || `https://${item.domain}`}
              target="_blank"
              rel="noopener noreferrer"
              initial={{ opacity: 0, scale: 0.95 }}
              animate={{ opacity: 1, scale: 1 }}
              exit={{ opacity: 0, scale: 0.95 }}
              transition={{ duration: 0.2, delay: idx * 0.05 }}
              className="bg-[#1C1712] border border-[#2C2419]/60 hover:border-[#E59500]/50 hover:bg-[#231F17]/40 rounded-2xl p-5 transition-all duration-300 group shadow-sm hover:shadow-lg hover:shadow-[#E59500]/5 transform hover:-translate-y-1 cursor-pointer flex flex-col justify-between"
            >
              <div className="flex flex-col gap-4">
                {/* Logo & Brand Info Container */}
                <div className="flex flex-col gap-3">
                  {/* Domain Real Logo / Favicon */}
                  <DomainLogoImage
                    domain={item.domain}
                    logoUrl={item.logoUrl}
                    alt={item.name}
                    className="w-16 h-16 sm:w-20 sm:h-20 border border-[#E59500]/20 group-hover:scale-105 transition-transform"
                  />
                  <div className="min-w-0">
                    <div className="flex items-center justify-between gap-1.5">
                      <p className="font-sans font-bold text-sm text-[#F9F7F2] tracking-tight group-hover:text-[#E59500] transition-colors truncate">
                        {item.name}
                      </p>
                      <ArrowUpRight className="w-4 h-4 text-[#6B6053] group-hover:text-[#E59500] group-hover:translate-x-0.5 group-hover:-translate-y-0.5 transition-all shrink-0" />
                    </div>
                    <div className="flex items-center justify-between gap-2 mt-1">
                      <span className="text-[10px] font-mono text-[#A69D92] hover:underline truncate">
                        {item.domain}
                      </span>
                      <span className="text-[9px] font-mono text-[#E59500] bg-[#E59500]/10 px-1.5 py-0.5 rounded border border-[#E59500]/15 shrink-0">
                        {item.pos}
                      </span>
                    </div>
                  </div>
                </div>

                {/* SEO Metric Stats */}
                <div className="grid grid-cols-3 gap-2 text-center border-t border-[#2C2419]/35 pt-4 mt-2">
                  <div>
                    <p className="text-xs font-mono text-[#E59500] font-bold tracking-tight">{item.clicks}</p>
                    <p className="text-[8px] text-[#6B6053] uppercase font-semibold font-mono tracking-wider">Clicks</p>
                  </div>
                  <div className="border-x border-[#2C2419]/35 px-1">
                    <p className="text-xs font-mono text-[#F9F7F2] font-semibold tracking-tight">{item.impressions}</p>
                    <p className="text-[8px] text-[#6B6053] uppercase font-semibold font-mono tracking-wider">Imprs</p>
                  </div>
                  <div>
                    <p className="text-xs font-mono text-[#A69D92] tracking-tight">{item.ctr}</p>
                    <p className="text-[8px] text-[#6B6053] uppercase font-semibold font-mono tracking-wider">CTR</p>
                  </div>
                </div>
              </div>
            </motion.a>
          ))}
        </AnimatePresence>
      </div>

      {totalPages > 1 && (
        <div className="flex justify-center items-center gap-6 mt-6 pt-4 border-t border-[#2C2419]/30">
          <button
            onClick={handlePrev}
            className="w-10 h-10 rounded-full border border-[#2C2419] bg-[#1C1712] text-[#A69D92] hover:border-[#E59500] hover:text-[#E59500] hover:bg-[#E59500]/10 flex items-center justify-center transition-all"
            aria-label="Previous page"
          >
            <ChevronLeft className="w-5 h-5" />
          </button>
          <span className="text-[11px] font-mono font-bold text-[#E59500]">
            {currentPage + 1} <span className="text-[#6B6053]">/</span> {totalPages}
          </span>
          <button
            onClick={handleNext}
            className="w-10 h-10 rounded-full border border-[#2C2419] bg-[#1C1712] text-[#A69D92] hover:border-[#E59500] hover:text-[#E59500] hover:bg-[#E59500]/10 flex items-center justify-center transition-all"
            aria-label="Next page"
          >
            <ChevronRight className="w-5 h-5" />
          </button>
        </div>
      )}
    </div>
  );
};


const VerifiedSearchDashboard = ({ items }: { items: any[] }) => {
  const [currentPage, setCurrentPage] = React.useState(0);
  const itemsPerPage = 6;
  const totalPages = Math.ceil(items.length / itemsPerPage);

  const handleNext = () => {
    setCurrentPage((prev) => (prev + 1) % totalPages);
  };

  const handlePrev = () => {
    setCurrentPage((prev) => (prev - 1 + totalPages) % totalPages);
  };

  const visibleItems = items.slice(currentPage * itemsPerPage, (currentPage + 1) * itemsPerPage);

  return (
    <div className="w-full">
      {/* Header and Controls */}
      <div className="flex flex-col sm:flex-row justify-between items-end sm:items-center mb-10 gap-4">
        <div>
          <h3 className="text-xl sm:text-2xl font-bold text-[#F9F7F2] flex items-center gap-3">
            <div className="w-10 h-10 rounded-xl bg-[#E59500]/10 flex items-center justify-center text-[#E59500]">
              <Search className="w-5 h-5" />
            </div>
            Google Search Console
          </h3>
          <p className="text-xs font-mono text-[#6B6053] mt-2">ORGANIC TRAFFIC PERFORMANCE (30D) • <span className="text-[#E59500]">VERIFIED DATA</span></p>
        </div>

        {totalPages > 1 && (
          <div className="flex items-center gap-3">
            <span className="text-xs font-mono text-[#A69D92] mr-2">
              {currentPage + 1} / {totalPages}
            </span>
            <button
              onClick={handlePrev}
              className="w-10 h-10 rounded-full border border-[#2C2419] bg-[#1C1712] text-[#F9F7F2] hover:border-[#E59500] hover:text-[#E59500] flex items-center justify-center transition-colors"
              aria-label="Previous page"
            >
              <ChevronLeft className="w-5 h-5" />
            </button>
            <button
              onClick={handleNext}
              className="w-10 h-10 rounded-full border border-[#2C2419] bg-[#1C1712] text-[#F9F7F2] hover:border-[#E59500] hover:text-[#E59500] flex items-center justify-center transition-colors"
              aria-label="Next page"
            >
              <ChevronRight className="w-5 h-5" />
            </button>
          </div>
        )}
      </div>

      {/* Grid of 6 Cards */}
      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6">
        <AnimatePresence mode="wait">
          {visibleItems.map((item, idx) => (
            <motion.a
              key={`${item.id || item.domain}-${currentPage}-${idx}`}
              href={item.url || `https://${item.domain}`}
              target="_blank"
              rel="noopener noreferrer"
              initial={{ opacity: 0, y: 20 }}
              animate={{ opacity: 1, y: 0 }}
              exit={{ opacity: 0, y: -20 }}
              transition={{ duration: 0.3, delay: idx * 0.05 }}
              className="block bg-[#1C1712] border border-[#2C2419]/60 hover:border-[#E59500]/50 hover:bg-[#231F17]/80 rounded-[20px] p-6 transition-all duration-300 group shadow-lg hover:shadow-xl hover:shadow-[#E59500]/10 transform hover:-translate-y-1 cursor-pointer relative overflow-hidden"
            >
              {/* Glass reflection effect */}
              <div className="absolute inset-0 bg-gradient-to-tr from-white/[0.02] to-transparent opacity-0 group-hover:opacity-100 transition-opacity duration-500 pointer-events-none" />

              <div className="flex flex-col h-full justify-between">
                <div>
                  <div className="flex justify-between items-start mb-6">
                    {/* Domain Real Logo / Favicon */}
                    <div className="p-2.5 bg-[#15120E] rounded-xl border border-[#2C2419] group-hover:scale-110 transition-transform duration-300 shadow-md">
                      <DomainLogoImage
                        domain={item.domain}
                        logoUrl={item.logoUrl}
                        alt={item.name}
                        className="w-10 h-10 sm:w-12 sm:h-12 object-contain"
                      />
                    </div>
                    <ArrowUpRight className="w-5 h-5 text-[#6B6053] group-hover:text-[#E59500] group-hover:translate-x-1 group-hover:-translate-y-1 transition-all" />
                  </div>

                  <h4 className="text-xl font-bold text-[#F9F7F2] tracking-tight group-hover:text-[#E59500] transition-colors mb-2 line-clamp-1">
                    {item.name}
                  </h4>

                  <div className="flex flex-wrap items-center gap-2 mb-6">
                    <span className="text-xs font-mono text-[#A69D92] group-hover:underline truncate max-w-full">
                      {item.domain}
                    </span>
                    <span className="w-1 h-1 rounded-full bg-[#2C2419] shrink-0" />
                    <span className="text-[10px] font-mono text-[#E59500] bg-[#E59500]/10 px-2 py-0.5 rounded-full border border-[#E59500]/15 shrink-0 flex items-center gap-1">
                      <CheckCircle2 className="w-3 h-3" />
                      VERIFIED
                    </span>
                  </div>
                </div>

                {/* SEO Metric Stats */}
                <div className="grid grid-cols-2 gap-y-4 gap-x-2 pt-5 border-t border-[#2C2419]/50">
                  <div>
                    <p className="text-base sm:text-lg font-mono text-[#F9F7F2] font-semibold tracking-tight">{item.impressions}</p>
                    <p className="text-[9px] text-[#6B6053] uppercase font-semibold font-mono tracking-wider mt-1">Impressions</p>
                  </div>
                  <div>
                    <p className="text-base sm:text-lg font-mono text-[#E59500] font-bold tracking-tight">{item.clicks}</p>
                    <p className="text-[9px] text-[#6B6053] uppercase font-semibold font-mono tracking-wider mt-1">Total Clicks</p>
                  </div>
                  <div>
                    <p className="text-sm sm:text-base font-mono text-[#F9F7F2] tracking-tight">{item.ctr}</p>
                    <p className="text-[9px] text-[#6B6053] uppercase font-semibold font-mono tracking-wider mt-1">Avg. CTR</p>
                  </div>
                  <div>
                    <p className="text-sm sm:text-base font-mono text-[#F9F7F2] tracking-tight">{item.pos}</p>
                    <p className="text-[9px] text-[#6B6053] uppercase font-semibold font-mono tracking-wider mt-1">Avg. Position</p>
                  </div>
                </div>
              </div>
            </motion.a>
          ))}
        </AnimatePresence>
      </div>
    </div>
  );
};

