                                      <h5 className="font-extrabold text-sm text-[#F9F7F2] pt-1">{b.clientName || 'Anonymous Client'}</h5>
                                      {b.company && <p className="text-[11px] text-[#A69D92] font-mono">{b.company}</p>}
